{
  "title": "Conversation Stats",
  "body": "<div class="panel"><h2>Conversation panel</h2><section><h3>Messages by role</h3><table><thead><tr><th>Role</th><th>Count</th></tr></thead><tbody id="roles"></tbody></table><p class="total" id="total"></p></section><section><h3>Five most recent tool calls</h3><ol id="calls"></ol></section><section><h3>Longest message</h3><p id="longest"></p></section></div>",
  "css": ".panel{font-family:system-ui,sans-serif;padding:12px;color:#222}h2{margin:0 0 12px;font-size:18px}h3{margin:14px 0 6px;font-size:14px;text-transform:uppercase;letter-spacing:.04em;color:#555}table{border-collapse:collapse;width:100%}th,td{text-align:left;padding:4px 8px;border-bottom:1px solid #ddd}td:last-child,th:last-child{text-align:right}.total{margin:6px 0 0;font-weight:600}ol{margin:0;padding-left:22px}li{padding:2px 0;font-family:ui-monospace,monospace}.empty{color:#888;font-style:italic;list-style:none;margin-left:-22px}#longest{margin:0}",
  "scripts": [
    "const msgs = (ml.current && ml.current.messages) || [];
const roleOrder = ['system','user','assistant','tool'];
const counts = {};
for (const r of roleOrder) { counts[r] = 0; }
for (const m of msgs) { counts[m.role] = (counts[m.role] ?? 0) + 1; }
const roleNames = roleOrder.concat(Object.keys(counts).filter(r => !roleOrder.includes(r)));
root.byId.roles.children = roleNames.map(r => ({ tag: 'tr', attrs: {}, text: '', children: [ { tag: 'td', attrs: {}, text: r, children: [] }, { tag: 'td', attrs: {}, text: String(counts[r]), children: [] } ] }));
root.byId.total.text = `Total: ${msgs.length} message${msgs.length === 1 ? '' : 's'}`;

const names = [];
for (const m of msgs) {
  if (m.tool_calls && m.tool_calls.length) {
    for (const tc of m.tool_calls) {
      names.push(tc?.function?.name ?? '(unknown)');
    }
  }
}
const recent = names.slice(-5).reverse();
root.byId.calls.children = recent.length
  ? recent.map(n => ({ tag: 'li', attrs: {}, text: n, children: [] }))
  : [{ tag: 'li', attrs: { class: 'empty' }, text: 'No tool calls yet', children: [] }];

let best = -1;
let bestIdx = -1;
msgs.forEach((m, i) => {
  const len = (typeof m.content === 'string' ? m.content : '').length;
  if (len > best) { best = len; bestIdx = i; }
});
root.byId.longest.text = bestIdx < 0
  ? 'No messages yet'
  : `${best} characters (message #${bestIdx + 1}, role: ${msgs[bestIdx].role})`;"
  ]
}
